#!/opt/homebrew/bin/zsh

# Copies the UI sources generated by EEZ Studio into this component.
# Build the project in the EEZ Studio GUI first: the command-line build
# (--build-project) in EEZ Studio 0.29 doesn't write the ui_font_*.c files.

GIT_DIR=$(git rev-parse --show-toplevel)
SRC_DIR=${GIT_DIR}/eez-studio/src/ui
DEST_DIR=${GIT_DIR}/esp-idf/components/ui

# Every font declared in fonts.h needs a matching source file
missing=()
for font in $(sed -n 's/^extern const lv_font_t \(ui_font_[a-z0-9_]*\);$/\1/p' ${SRC_DIR}/fonts.h)
do
    [[ -f ${SRC_DIR}/${font}.c ]] || missing+=(${font})
done
if (( ${#missing} ))
then
    echo "Missing font sources in ${SRC_DIR}: ${missing[*]}" >&2
    echo "Build the project in the EEZ Studio GUI to generate them." >&2
    exit 1
fi

rm -f ${DEST_DIR}/*.c(N) ${DEST_DIR}/*.h(N)
cp ${SRC_DIR}/*.c ${SRC_DIR}/*.h ${DEST_DIR}
